#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
using namespace std;

int gcd(int a, int b) {
    while (b != 0) {
        int temp = a % b;
        a = b;
        b = temp;
    }
    return a;
}

int main() {
    string line;
    getline(cin, line);
    vector<int> nums;
    size_t pos = 0;
    while ((pos = line.find(' ')) != string::npos) {
        nums.push_back(stoi(line.substr(0, pos)));
        line.erase(0, pos + 1);
    }
    nums.push_back(stoi(line));
    sort(nums.begin(), nums.end());
    int a = nums[0];
    int b = nums[1];
    int c = 7 - b;
    int g = gcd(c, 6);
    cout << c/g << "/" << 6/g << endl;
    return 0;
}

